let count = 0;

function Counter() {
  function handleClick() {
    count += 1;
    console.log('변수 count:', count);
  }

  return (
    <section>
      <p>화면 숫자: {count}</p>
      <button type="button" onClick={handleClick}>증가</button>
    </section>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Counter />);

